def assign_index_shard(doc_id: str, num_shards: int = 32) -> int:
    import hashlib
    return int(hashlib.md5(doc_id.encode()).hexdigest(), 16) % num_shards

def rewrite_query(raw_q: str, synonyms: dict) -> dict:
    tokens = raw_q.lower().split()
    expanded = [synonyms.get(t, [t]) for t in tokens]
    return {'must': tokens, 'should_expand': expanded}

def gather_with_degradation(shard_futures: list, min_shards_ratio: float = 0.9) -> list:
    completed = [f.result() for f in shard_futures if f.done() and not f.exception()]
    if len(completed) / len(shard_futures) < min_shards_ratio:
        raise RuntimeError('Too many index shards unavailable')
    return completed

def score_ltr_batch(model, feature_matrix: list[list[float]], doc_ids: list[str]) -> list[tuple]:
    scores = model.predict(feature_matrix)
    return sorted(zip(doc_ids, scores), key=lambda x: x[1], reverse=True)

def emit_search_telemetry(producer, query_id: str, doc_id: str, event_type: str, pos: int) -> None:
    producer.send('search.telemetry', {
        'query_id': query_id, 'doc_id': doc_id, 'event': event_type, 'pos': pos
    })
